const extractRawText = (item) =>
  item.json.output?.[0]?.content?.[0]?.text ||
  item.json.output?.[0]?.text ||
  item.json.content?.[0]?.text ||
  item.json.text ||
  item.json.response ||
  item.json.message ||
  '';

const extractJobId = (url) =>
  String(url || '').match(/jobs\/view\/(\d+)/)?.[1] || '';

// BG-ONLY: accept Bulgaria, Sofia, Remote Bulgaria only. Reject broad international remote.
const assessBulgariaOnlyLocation = (location, workType = '') => {
  const loc = String(location || '').toLowerCase().trim();
  const wt = String(workType || '').toLowerCase().trim();

  if (/relocation|relocate\s*(?:required|to\b)/.test(loc)) {
    return { allowed: false, reason: 'Relocation required.' };
  }

  if (
    /remote europe/.test(loc) ||
    /remote emea/.test(loc) ||
    /emea · remote/.test(loc) ||
    /europe · remote/.test(loc) ||
    /remote worldwide/.test(loc) ||
    /remote global/.test(loc) ||
    /work from anywhere in europe/.test(loc) ||
    /any european countr/.test(loc)
  ) {
    return { allowed: false, reason: 'Remote Europe/EMEA/Worldwide rejected (BG-only workflow).' };
  }

  if (/\bsofia\b/.test(loc) || /remote bulgaria/.test(loc) || /bulgaria · remote/.test(loc)) {
    return { allowed: true, reason: '' };
  }

  if (loc.includes('bulgaria')) {
    return { allowed: true, reason: '' };
  }

  const hasRemote = wt === 'remote' || /\bremote\b/.test(loc);
  const hasHybrid = wt === 'hybrid' || /\bhybrid\b/.test(loc);
  const hasOnsite =
    wt === 'onsite' ||
    wt === 'on-site' ||
    /\bon-?site\b/.test(loc) ||
    /\bonsite\b/.test(loc);

  const foreignCountryPattern =
    /\b(united kingdom|uk|great britain|england|netherlands|spain|france|italy|germany|portugal|switzerland|austria|belgium|ireland|poland|romania|hungary|sweden|norway|denmark|finland|usa|united states|u\.s\.|canada|australia)\b/;

  if (hasRemote && (loc.includes('· remote') || foreignCountryPattern.test(loc))) {
    return { allowed: false, reason: 'Country-specific remote outside Bulgaria rejected.' };
  }

  if (hasHybrid && !loc.includes('bulgaria') && !/\bsofia\b/.test(loc)) {
    return { allowed: false, reason: 'Hybrid outside Bulgaria rejected.' };
  }

  if (hasOnsite && !loc.includes('bulgaria') && !/\bsofia\b/.test(loc)) {
    return { allowed: false, reason: 'On-site outside Bulgaria rejected.' };
  }

  if (hasRemote && !loc.includes('bulgaria') && !/\bsofia\b/.test(loc)) {
    return { allowed: false, reason: 'Ambiguous international remote location rejected (BG-only workflow).' };
  }

  if (!hasRemote && foreignCountryPattern.test(loc)) {
    return { allowed: false, reason: 'Non-Bulgaria location rejected.' };
  }

  if (!loc || loc === 'not specified') {
    return { allowed: false, reason: 'Ambiguous location — BG-only workflow requires Bulgaria, Sofia, or Remote Bulgaria.' };
  }

  return { allowed: false, reason: 'Location not clearly Bulgaria, Sofia, or Remote Bulgaria.' };
};

const locationAllowed = (location, workType = '') =>
  assessBulgariaOnlyLocation(location, workType).allowed;

const locationRejectReason = (location, workType, allowed) => {
  if (allowed) return '';
  return assessBulgariaOnlyLocation(location, workType).reason;
};

const looksFakeCompany = (company, role) => {
  const c = String(company || '').toLowerCase().trim();
  const r = String(role || '').toLowerCase().trim();

  if (!c) return true;
  if (c === r) return true;

  const blockedExactCompanies = [
    'remote',
    'hybrid',
    'onsite',
    'on-site',
    'on site',
    'full-time',
    'part-time',
    'contract',
    'temporary',
    'internship'
  ];

  if (blockedExactCompanies.includes(c)) return true;

  if (
    c.includes('connections') ||
    c.includes('install linkedin widgets') ||
    c.includes('see all jobs') ||
    c.includes('actively recruiting') ||
    c.includes('actively reviewing applicants') ||
    c.includes('fast growing') ||
    c.includes('promoted by hirer') ||
    c.includes('responses managed off linkedin')
  ) return true;

  const roleWords = [
    'manager', 'director', 'head', 'chief', 'vp',
    'operations', 'revenue', 'strategy', 'business',
    'lead', 'program', 'product', 'commercial', 'revops'
  ];

  return roleWords.some(w => c.includes(w));
};

const inferWorkType = (text) => {
  const t = String(text || '').toLowerCase();
  if (/\bremote\b/.test(t)) return 'Remote';
  if (/\bhybrid\b/.test(t)) return 'Hybrid';
  if (/\b(on-?site|on site)\b/.test(t)) return 'Onsite';
  return '';
};

const parseLocationFromText = (text) => {
  const t = String(text || '');
  const lower = t.toLowerCase();
  const workType = inferWorkType(t);

  if (/remote europe/.test(lower)) return 'Remote Europe';
  if (/remote emea/.test(lower)) return 'Remote EMEA';
  if (/remote worldwide|remote global/.test(lower)) return 'Remote Worldwide';

  const countries = [
    ['bulgaria', 'Bulgaria'],
    ['united kingdom', 'United Kingdom'],
    ['portugal', 'Portugal'],
    ['italy', 'Italy'],
    ['france', 'France'],
    ['switzerland', 'Switzerland'],
    ['netherlands', 'Netherlands'],
    ['germany', 'Germany'],
    ['spain', 'Spain'],
    ['united states', 'United States'],
  ];

  for (const [needle, label] of countries) {
    if (lower.includes(needle)) {
      return workType ? `${label} · ${workType}` : label;
    }
  }

  return 'Not specified';
};

const buildDeterministicJobs = (content) => {
  const hints = content.JobUrlHints || [];
  const subjectHint = content.SubjectJobHint || {};
  const jobs = [];

  const skipLine = (line, role) =>
    !line ||
    line === role ||
    /^(apply|save|easy apply|full-time|part-time|promoted|similar jobs|view job|see all jobs)$/i.test(line) ||
    /^(remote|hybrid|on-?site|on site)$/i.test(line) ||
    /^\d+ (connection|mutual)/i.test(line);

  for (const hint of hints) {
    const url = String(hint.url || '').trim();
    if (!url) continue;

    const role = String(hint.anchorText || subjectHint.role || '').trim();
    const contextLines = String(hint.context || '')
      .split('\n')
      .map((l) => l.trim())
      .filter(Boolean);

    let company = '';

    if (hints.length === 1 && subjectHint.company) {
      company = String(subjectHint.company).trim();
    }

    if (!company) {
      company = contextLines.find((l) => !skipLine(l, role) && l.length <= 80) || '';
    }

    if (!company || !role) continue;

    jobs.push({
      company,
      role,
      location: parseLocationFromText(hint.context),
      work_type: inferWorkType(hint.context),
      url,
    });
  }

  if (jobs.length === 0 && hints.length === 1 && subjectHint.company && subjectHint.role) {
    jobs.push({
      company: String(subjectHint.company).trim(),
      role: String(subjectHint.role).trim(),
      location: parseLocationFromText(content.EmailText || ''),
      work_type: inferWorkType(content.EmailText || ''),
      url: String(hints[0].url || '').trim(),
    });
  }

  return jobs;
};

const isSimilarJobsCarouselSubject = (subject) => {
  const s = String(subject || '').trim();
  if (!s) return false;
  const tail = s.includes(':') ? s.split(':').pop().trim() : s;
  if (/\bsimilar\s+jobs\s*$/i.test(tail)) return true;
  if (/\bOR\b.+\bsimilar\s+jobs\b/i.test(tail)) return true;
  if (/\bjobs\s+similar\s+to\b/i.test(tail)) return true;
  return false;
};

const buildSubjectFallbackJobs = (content) => {
  const subjectHint = content.SubjectJobHint || {};
  const company = String(subjectHint.company || '').trim();
  const role = String(subjectHint.role || '').trim();
  if (!company || !role) return [];
  if (isSimilarJobsCarouselSubject(content.EmailSubject || content.Subject || '')) return [];

  const hints = content.JobUrlHints || [];
  const url = hints.length ? String(hints[0].url || '').trim() : '';
  const locSource = [content.EmailSnippet, content.EmailText, content.emailText]
    .filter(Boolean)
    .join(' ');

  return [
    {
      company,
      role,
      location: parseLocationFromText(locSource),
      work_type: inferWorkType(locSource),
      url,
      subjectFallback: true,
    },
  ];
};

const normalizeEmailItems = $('Normalize Email Content').all();

const getEmailFields = (index) => {
  const emailMeta = normalizeEmailItems[index]?.json || {};

  return {
    EmailId: emailMeta.EmailId || '',
    ThreadId: emailMeta.ThreadId || '',
    EmailReceived: emailMeta.EmailReceived || '',
    EmailSubject: emailMeta.EmailSubject || '',
    EmailSnippet: emailMeta.EmailSnippet || '',
    TestMode: emailMeta.TestMode ?? '',
    TestLabelUsed: emailMeta.TestLabelUsed ?? '',
    GmailLabels: emailMeta.GmailLabels ?? '',
  };
};

const buildFallbackItem = (emailFields, extractionError = 'AI Extract returned []') => ({
  json: {
    ...emailFields,
    Source: 'LinkedIn Email',
    Status: 'Rejected',
    Apply: 'NO',
    Recommendation: 'NO',
    Reason: 'AI Extract returned no job cards',
    RejectReason: 'AI Extract returned no job cards',
    MainRisk: 'No job card parsed from email',
    Risk: 'No job card parsed from email',
    Role: '',
    Company: '',
    Location: '',
    URL: '',
    JobUrl: '',
    JobId: '',
    WorkType: '',
    DedupeKey: emailFields.EmailId || '',
    ExtractionStatus: 'NO_JOB_CARD',
    ExtractionError: extractionError,
    PipelineStage: 'NO_JOB_CARD',
    LocationAllowed: true,
    LocationRejectReason: 'AI Extract returned no job cards',
    Notes: '',
    ParseError: '',
  },
});

const output = [];
const seen = new Set();
const inputItems = $input.all();

for (let inputIndex = 0; inputIndex < inputItems.length; inputIndex++) {
  const item = inputItems[inputIndex];
  const emailFields = getEmailFields(inputIndex);
  const raw = extractRawText(item);

  let clean = String(raw)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const firstBracket = clean.indexOf('[');
  const lastBracket = clean.lastIndexOf(']');

  if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
    clean = clean.slice(firstBracket, lastBracket + 1);
  }

  let parsed;

  try {
    parsed = JSON.parse(clean);
  } catch (e) {
    output.push(buildFallbackItem(emailFields, 'AI Extract returned invalid JSON'));
    continue;
  }

  const jobs = Array.isArray(parsed) ? parsed : (parsed.jobs || []);

  let jobList = jobs;

  if (jobList.length === 0) {
    const content = normalizeEmailItems[inputIndex]?.json || {};
    jobList = buildDeterministicJobs(content);

    if (jobList.length === 0) {
      jobList = buildSubjectFallbackJobs(content);
    }

    if (jobList.length === 0) {
      output.push(buildFallbackItem(emailFields));
      continue;
    }
  }

  let addedForEmail = false;

  for (const j of jobList) {
    if (!j || !j.company || !j.role) continue;
    if (looksFakeCompany(j.company, j.role)) continue;

    const company = String(j.company || '').trim();
    const role = String(j.role || '').trim();
    const location = String(j.location || 'Not specified').trim();
    const workType = String(j.work_type || '').trim();
    const url = String(j.url || '').trim();
    const jobId = extractJobId(url);
    const dedupeKey = (jobId || `${company}|${role}|${location}`).toLowerCase();

    if (!dedupeKey || dedupeKey === '||') continue;
    if (seen.has(dedupeKey)) continue;

    seen.add(dedupeKey);
    addedForEmail = true;

    const allowed = locationAllowed(location, workType);

    output.push({
      json: {
        ...emailFields,
        Role: role,
        Company: company,
        JobId: jobId,
        Location: location,
        WorkType: workType,
        URL: url,
        LocationAllowed: allowed,
        LocationRejectReason: locationRejectReason(location, workType, allowed),
        Source: 'LinkedIn',
        Status: 'New',
        ExtractionStatus: j.subjectFallback ? 'SUBJECT_FALLBACK' : '',
        Notes: j.subjectFallback ? 'Subject fallback; card extraction failed' : '',
        ExtractionError: j.subjectFallback ? 'Subject fallback; card extraction failed' : '',
        ParseError: '',
        DedupeKey: dedupeKey
      }
    });
  }

  if (!addedForEmail) {
    output.push(buildFallbackItem(emailFields, 'AI Extract returned no valid job cards'));
  }
}

return output;

// DEV-ONLY: set to true to inject a low-fit mock job and bypass Gmail parse output.
// Must remain false for normal DEV/production runs.
const DEV_TEST_MODE_ENABLED = false;

if (!DEV_TEST_MODE_ENABLED) {
  return $input.all();
}

return [
  {
    json: {
      EmailId: 'test-low-fit-email',
      ThreadId: 'test-low-fit-thread',
      EmailReceived: String(Date.now()),
      EmailSubject: 'TEST low fit job',
      EmailSnippet: 'Entry-level customer support role in the United States, on-site.',
      Role: 'Junior Customer Support Agent',
      Company: 'Test Company',
      Location: 'United States · On-site',
      URL: 'https://example.com/test-job',
      JobUrl: 'https://example.com/test-job',
      JobId: '',
      WorkType: 'Onsite',
      Source: 'TEST',
      Status: 'New',
      Notes: '',
      ParseError: '',
      DedupeKey: 'test-low-fit-job',
      LocationAllowed: false,
      LocationRejectReason: 'Country-specific or non-Bulgaria location rejected.',
      DevTestMode: true,
      DevTestCase: 'LOW_PREVIEW_SCORE',
    },
  },
];

const url = String($json.URL || '').trim();

return {
  json: {
    ...$json,
    HardReject: false,
    RejectReason: '',
    NeedsEnrichment: url.includes('/jobs/view/'),
    PolicyVersion: '1.1-BG-ONLY',
    PipelineStage: $json.ExtractionStatus === 'NO_JOB_CARD' ? 'NO_JOB_CARD' : ($json.HardReject === true ? 'POLICY_REJECT' : ''),
  },
};

// Preview gate threshold — change PreviewScoreThreshold here only.
// TEMP BG calibration: PreviewScoreThreshold = 6 (was 7). May revert to 7 after testing.
// Score >= 6 opens full posting / verified review; preview YES and final APPLY stay strict (7+ / verified stage).
// PREVIEW STAGE FIELDS (email card only): PreviewScore, PreviewRecommendation, PreviewReason, PreviewRisk, PreviewCV
// Do not write Score or VerifiedScore here.
const PreviewScoreThreshold = 6;
const PreviewRecommendYesThreshold = 7;
const VerifiedScoreThreshold = 7;

const base = $('Policy Engine').item?.json || {};

const allowedCvs = [
  'COO CV',
  'GTM & Commercial Operations CV',
  'Strategy & Operations CV',
  'AI Transformation CV',
  'Project / Program Leadership CV',
];

const normalizeCv = (cv) => {
  const value = String(cv || '').trim();
  return allowedCvs.includes(value) ? value : 'Strategy & Operations CV';
};

const normalizePreviewRoleTitle = (role) => {
  let value = String(role || '').trim();
  value = value.replace(/\bcomersial\b/gi, 'Commercial');
  return value;
};

const clampScore = (score) => {
  const n = Number(score);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(10, Math.round(n)));
};

const isBulgariaEligibleLocation = (location, workType = '') => {
  const loc = String(location || '').toLowerCase().trim();
  const wt = String(workType || '').toLowerCase().trim();
  if (/\bsofia\b/.test(loc) || /remote bulgaria/.test(loc) || /bulgaria · remote/.test(loc)) return true;
  return loc.includes('bulgaria');
};

const BG_EXECUTIVE_TITLE_PATTERNS = [
  /business support and operations director/i,
  /\boperations director\b/i,
  /\bhead of operations\b/i,
  /\btransformation director\b/i,
  /\bmanaging director\b/i,
  /\bgeneral manager\b/i,
  /\bchief operating officer\b/i,
  /\bvp operations\b/i,
  /\bvice president operations\b/i,
  /\bcommercial director\b/i,
  /\bglobal practice leader\b/i,
  /\bcomersial director\b/i,
  /\bcoo\b/i,
];

const hasClearJuniorPreviewEvidence = (role) => {
  const r = String(role || '').toLowerCase();
  if (BG_EXECUTIVE_TITLE_PATTERNS.some((pattern) => pattern.test(r))) return false;
  return /\b(junior|intern|coordinator|analyst|assistant to|executive assistant|support agent|customer support|administrator|admin\b|team lead|specialist)\b/.test(r);
};

const matchesBgExecutiveTitle = (role) =>
  BG_EXECUTIVE_TITLE_PATTERNS.some((pattern) => pattern.test(String(role || '')));

const SPECIALIZED_DOMAIN_CARD_PATTERNS = [
  { re: /\bcommercial vehicles?\b/i, label: 'commercial vehicles' },
  { re: /\bused trucks?\b/i, label: 'used trucks' },
  { re: /\btruck remarketing\b/i, label: 'truck remarketing' },
  { re: /\bautomotive remarketing\b/i, label: 'automotive remarketing' },
  { re: /\brenault trucks\b/i, label: 'commercial vehicles' },
  { re: /\bpharmaceutical manufacturing\b/i, label: 'pharmaceutical manufacturing' },
  { re: /\bclinical operations\b/i, label: 'clinical operations' },
  { re: /\bsemiconductor manufacturing\b/i, label: 'semiconductor manufacturing' },
  { re: /\baviation\b/i, label: 'aviation' },
  { re: /\bused vehicle\b/i, label: 'automotive remarketing' },
];

const detectSpecializedDomainCard = (role, company, snippet = '') => {
  const text = `${role || ''} ${company || ''} ${snippet || ''}`.trim();
  if (!text) return { hit: false, label: '' };
  for (const item of SPECIALIZED_DOMAIN_CARD_PATTERNS) {
    if (item.re.test(text)) return { hit: true, label: item.label };
  }
  return { hit: false, label: '' };
};

const applyBgExecutiveTitlePreviewCalibration = (score, role, location, workType, company, snippet) => {
  if (!isBulgariaEligibleLocation(location, workType)) return { score, calibrated: false, domainLimited: false };
  if (hasClearJuniorPreviewEvidence(role)) return { score, calibrated: false, domainLimited: false };
  if (!matchesBgExecutiveTitle(role)) return { score, calibrated: false, domainLimited: false };
  let floored = Math.max(clampScore(score), 6);
  const domain = detectSpecializedDomainCard(role, company, snippet);
  if (domain.hit && floored > 7) floored = 7;
  return {
    score: floored,
    calibrated: floored !== clampScore(score),
    domainLimited: domain.hit,
    domainLabel: domain.label,
  };
};

const looksLikeLocationDecision = (text) => {
  const t = String(text || '').toLowerCase();
  if (!t.trim()) return false;
  return (
    /remote not acceptable|not acceptable for|country-specific remote|country specific remote|work authorization|residents only|uk remote|united kingdom remote|spain remote|netherlands remote|france remote|italy remote|bulgaria allowed|non-bulgaria|location reject|relocation required|outside bulgaria/.test(t) &&
    !/role|seniority|function|company|executive|coo|operations|transformation|junior|support/.test(t)
  );
};

const sanitizeBulgarianLanguageRisk = (text) => {
  const value = String(text || '').trim();
  if (!value) return value;

  const parts = value
    .split(/\s*(?:\||;)\s*/)
    .map((part) => part.trim())
    .filter(Boolean);

  const kept = parts.filter((part) => {
    const lower = part.toLowerCase();
    if (!/\bbulgarian\b/.test(lower)) return true;
    if (/unconfirmed|unclear|not confirmed|unknown requirement|language risk|fluency.*(?:unclear|unconfirmed)|not in profile|may not meet|lack(?:s|ing)?/.test(lower)) {
      return false;
    }
    if (/fluent bulgarian|bulgarian language|native bulgarian|bulgarian fluency|bulgarian proficiency/.test(lower)) {
      return false;
    }
    return true;
  });

  if (!kept.length) return '';
  return kept.join(' | ');
};

const sanitizePreviewText = (text, fallback) => {
  const value = String(text || '').trim();
  if (!value) return fallback;
  if (looksLikeLocationDecision(value)) return fallback;
  return sanitizeBulgarianLanguageRisk(value) || fallback;
};

const skipPreview =
  base.ExtractionStatus === 'NO_JOB_CARD' ||
  (!String(base.Role || '').trim() && !String(base.Company || '').trim());

if (skipPreview) {
  return {
    json: {
      ...base,
      PreviewScore: 0,
      PreviewRecommendation: 'NO',
      PreviewReason: base.ExtractionError || base.RejectReason || 'No job card parsed from email',
      PreviewRisk: base.MainRisk || 'No job card parsed from email',
      PreviewCV: 'Strategy & Operations CV',
      PreviewScoreThreshold,
      PreviewPassesThreshold: false,
      PipelineStage: 'NO_JOB_CARD',
    },
  };
}

const raw =
  $json.output?.[0]?.content?.[0]?.text ||
  $json.output?.[0]?.text ||
  $json.content?.[0]?.text ||
  $json.text ||
  '';

const clean = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let ai = {};

try {
  ai = JSON.parse(clean);
} catch (e) {
  ai = {};
}

const normalizedRole = normalizePreviewRoleTitle(base.Role);
const rawPreviewScore = clampScore(ai.preview_score);
const domainCard = detectSpecializedDomainCard(normalizedRole, base.Company, base.EmailSnippet);
const calibration = applyBgExecutiveTitlePreviewCalibration(
  rawPreviewScore,
  normalizedRole,
  base.Location,
  base.WorkType,
  base.Company,
  base.EmailSnippet,
);
let previewScore = calibration.score;
if (domainCard.hit && previewScore > 7) previewScore = 7;
const previewPassesThreshold = previewScore >= PreviewScoreThreshold;

const normalizePreviewRecommendation = (rec, score, passThreshold, yesThreshold) => {
  let value = String(rec || '').trim().toUpperCase();
  if (!['YES', 'MONITOR', 'NO'].includes(value)) {
    if (score >= yesThreshold) value = 'YES';
    else if (score >= passThreshold) value = 'MONITOR';
    else if (score >= 5) value = 'MONITOR';
    else value = 'NO';
  }
  if (value === 'YES' && score < yesThreshold) value = 'MONITOR';
  return value;
};

let previewRecommendation = normalizePreviewRecommendation(
  ai.preview_recommendation,
  previewScore,
  PreviewScoreThreshold,
  PreviewRecommendYesThreshold,
);
if (domainCard.hit && previewScore <= 7 && previewRecommendation === 'YES') {
  previewRecommendation = 'MONITOR';
}

const domainFallbackReason =
  'Executive title match with specialized industry on card; open full posting to verify domain transferability.';
const domainFallbackRisk =
  'Industry-specific experience may be an important differentiator; scope and P&L should be verified in full posting.';

const previewReason = sanitizePreviewText(
  ai.preview_reason,
  calibration.domainLimited || domainCard.hit
    ? domainFallbackReason
    : calibration.calibrated
      ? 'BG executive title match — company/seniority unclear from card; worth full posting review.'
      : 'Card-level role/seniority fit assessed; location eligibility deferred to full job read.',
);
const previewRisk = sanitizePreviewText(
  ai.preview_risk,
  calibration.domainLimited || domainCard.hit
    ? domainFallbackRisk
    : calibration.calibrated
      ? 'Company brand/seniority unclear from email card; verify scope in full LinkedIn posting.'
      : 'Location eligibility unknown from email card; verify after full LinkedIn posting read.',
);

return {
  json: {
    ...base,
    PreviewScore: previewScore,
    PreviewRecommendation: previewRecommendation,
    PreviewReason: previewReason,
    PreviewRisk: previewRisk,
    PreviewCV: normalizeCv(ai.preview_cv),
    PreviewScoreThreshold,
    PreviewPassesThreshold: previewPassesThreshold,
    VerifiedScoreThreshold,
  },
};

// Preview reject — keep Preview* intact; Verified* empty; Score mapped at Sheets only.
// Runs ONLY on Check Preview Threshold FALSE branch (PreviewPassesThreshold === false).
return {
  json: {
    ...$json,
    Status: 'Rejected',
    RejectReason: 'Preview score below threshold',
    FinalDecision: 'REJECT_PREVIEW',
    PipelineStage: $json.ExtractionStatus === 'NO_JOB_CARD' ? 'NO_JOB_CARD' : 'PREVIEW_REJECT',
    VerifiedScore: '',
    VerifiedRecommendation: '',
    VerifiedRisk: '',
    VerifiedWhyApply: '',
    FinalCV: '',
    VerifiedInterviewProbability: '',
    VerifiedPriority: '',
    SalaryEstimate: '',
    SalaryTarget: '',
    SalaryConfidence: '',
    SalaryAssumption: '',
    LocationFit: '',
  },
};

const config = $input.first().json;
const LINKEDIN_LABEL_ID = 'Label_3053362597517296520';

const asBool = (v) => v === true || v === 'true' || v === 1;
