const normalizeJobUrl = (raw) => {
  const decoded = decodeHtml(String(raw || '')).trim();
  const jobId = decoded.match(/linkedin\.com(?:\/comm)?\/jobs\/view\/(\d+)/i)?.[1];
  return jobId ? `https://www.linkedin.com/jobs/view/${jobId}` : '';
};

const cleanText = (html) =>
  decodeHtml(html)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<\/td>/gi, '\n')
    .replace(/<\/h[1-6]>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\n+/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .split('\n')
    .map(x => x.trim())
    .filter(Boolean)
    .join('\n')
    .trim();

const extractLinkedInJobUrls = (html) => {
  const matches =
    String(html || '').match(
      /https?:\/\/(?:[a-z0-9-]+\.)*linkedin\.com(?:\/comm)?\/jobs\/view\/\d+[^"'<\s]*/gi,
    ) || [];
  const seen = new Set();

  return matches
    .map((u) => normalizeJobUrl(u))
    .filter((u) => {
      const id = u.match(/jobs\/view\/(\d+)/)?.[1] || '';
      if (!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
};

const normalizeSubjectDashes = (text) =>
  String(text || '').replace(/[–—]/g, '-');

const isCarouselSubjectRole = (role) => {
  const r = String(role || '').trim();
  if (!r) return true;
  if (/\bsimilar\s+jobs\b/i.test(r)) return true;
  if (/\bor\b/i.test(r) && /\bsimilar\s+jobs\b/i.test(r)) return true;
  return false;
};

const parseSubjectJobHint = (subject) => {
  const s = normalizeSubjectDashes(decodeHtml(String(subject || ''))).trim();
  if (!s) return { company: '', role: '' };

  const tail = s.includes(':') ? s.split(':').pop().trim() : s;

  const posted = tail.match(/^(.+?)\s+-\s+(.+?)\s+posted\s+on\b/i);
  if (posted) {
    const company = posted[1].trim();
    const role = posted[2].trim();
    if (company && role && !isCarouselSubjectRole(role)) {
      return { company, role };
    }
  }

  if (!s.includes(':') || s.indexOf(':') === s.lastIndexOf(':')) {
    const colonPosted = s.match(/^([^:]+):\s*(.+?)\s+posted\s+on\b/i);
    if (colonPosted) {
      const company = colonPosted[1].trim();
      const role = colonPosted[2].trim();
      if (company && role && !isCarouselSubjectRole(role) && role.length < 120) {
        return { company, role };
      }
    }
  }

  for (const candidate of [tail, s]) {
    const dashed = candidate.match(/^(.+?)\s+-\s+(.+)$/);
    if (dashed) {
      const company = dashed[1].trim();
      let role = dashed[2].trim();
      role = role.replace(/\s+posted\s+on\b.*$/i, '').trim();
      if (company && role && !isCarouselSubjectRole(role) && role.length < 120) {
        return { company, role };
      }
    }
  }

  return { company: '', role: '' };
};

const extractAnchorJobHints = (html) => {
  const hints = [];
  const seen = new Set();
  const re = /<a[^>]+href=["']([^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let match;

  while ((match = re.exec(String(html || ''))) !== null) {
    const url = normalizeJobUrl(match[1]);
    if (!url) continue;

    const jobId = url.match(/jobs\/view\/(\d+)/)?.[1] || '';
    if (!jobId || seen.has(jobId)) continue;
    seen.add(jobId);

    hints.push({
      url,
      jobId,
      anchorText: cleanText(match[2]),
      context: cleanText(String(html || '').slice(match.index, match.index + 1200)).slice(0, 500),
    });
  }

  return hints;
};

const formatJobHintsForAI = (hints, subjectHint) => {
  const lines = [];
  if (subjectHint.company || subjectHint.role) {
    lines.push(`Subject hint: company="${subjectHint.company}" role="${subjectHint.role}"`);
  }
  hints.forEach((h, i) => {
    lines.push(`Job block ${i + 1}:`);
    lines.push(`  URL: ${h.url}`);
    if (h.anchorText) lines.push(`  Link text: ${h.anchorText}`);
    if (h.context) lines.push(`  Nearby text: ${h.context}`);
  });
  return lines.join('\n');
};

