const isCountrySpecificRemote = (location, workType = '') => {
  const loc = String(location || '').toLowerCase().trim();
  const wt = String(workType || '').toLowerCase().trim();
  const hasRemote = wt === 'remote' || /\bremote\b/.test(loc);
  if (!hasRemote) return false;
  if (/remote europe|remote emea|remote worldwide|remote global|bulgaria/.test(loc)) return false;
  if (loc.includes('· remote')) return true;
  return /\b(united kingdom|uk|spain|netherlands|france|germany|italy|portugal|switzerland)\b/.test(loc);
};

const looksLikeCardLocationRejection = (text) => {
  const t = String(text || '').toLowerCase();
  return /country-specific|not acceptable|residents only|work authorization|outside bulgaria|uk remote|united kingdom remote|spain remote|netherlands remote|france remote|germany remote|location mismatch|location reject/.test(t);
};

const LOCATION_REVIEW_MSG = 'Location eligibility requires full posting verification.';

const sanitizeBulgarianLanguageRisk = (text) => {
  const value = String(text || '').trim();
  if (!value) return value;

  const parts = value
    .split(/\s*(?:\||;)\s*/)
    .map((part) => part.trim())
    .filter(Boolean);

  const kept = parts.filter((part) => {
    const lower = part.toLowerCase();
    if (!/\bbulgarian\b/.test(lower)) return true;
    if (/unconfirmed|unclear|not confirmed|unknown requirement|language risk|fluency.*(?:unclear|unconfirmed)|not in profile|may not meet|lack(?:s|ing)?/.test(lower)) {
      return false;
    }
    if (/fluent bulgarian|bulgarian language|native bulgarian|bulgarian fluency|bulgarian proficiency/.test(lower)) {
      return false;
    }
    return true;
  });

  if (!kept.length) return '';
  return kept.join(' | ');
};

const clampInterviewProbability = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  const pct = n >= 0 && n <= 10 ? Math.round(n * 10) : Math.round(n);
  return Math.max(0, Math.min(100, pct));
};

const normalizeTriFit = (value, fallback = 'PARTIAL') => {
  const v = String(value || '').trim().toUpperCase();
  if (v === 'FULL MATCH' || v === 'FULL_MATCH') return 'FULL MATCH';
  if (v === 'PARTIAL') return 'PARTIAL';
  if (v === 'WEAK') return 'WEAK';
  return fallback;
};

const normalizeGeoFit = (value, fallback = 'REVIEW_REQUIRED') => {
  const v = String(value || '').trim().toUpperCase();
  if (v === 'FULL MATCH' || v === 'FULL_MATCH') return 'FULL MATCH';
  if (v === 'REVIEW_REQUIRED') return 'REVIEW_REQUIRED';
  if (v === 'MISMATCH') return 'MISMATCH';
  return fallback;
};

const normalizeRecommendation = (value, fallback = 'NO') => {
  const v = String(value || '').trim().toUpperCase();
  if (['YES', 'MONITOR', 'NO'].includes(v)) return v;
  return fallback;
};

const normalizePriority = (value, fallback = 'LOW') => {
  const v = String(value || '').trim().toUpperCase();
  if (['HIGH', 'MEDIUM', 'LOW'].includes(v)) return v;
  return fallback;
};

const sanitizeInitialEvalLocation = (ai, location, workType, previewCtx) => {
  if (!isCountrySpecificRemote(location, workType)) return ai;
  const out = { ...ai };
  const hadLocationReject =
    ['NO', 'MISMATCH'].includes(String(out.country_fit || '').toUpperCase()) ||
    ['NO', 'MISMATCH'].includes(String(out.location_fit || '').toUpperCase()) ||
    ['NO', 'MISMATCH'].includes(String(out.remote_fit || '').toUpperCase()) ||
    looksLikeCardLocationRejection(out.main_risk);

  out.country_fit = 'REVIEW_REQUIRED';
  out.location_fit = 'REVIEW_REQUIRED';
  if (['NO', 'MISMATCH', 'UNKNOWN', ''].includes(String(out.remote_fit || '').toUpperCase())) {
    out.remote_fit = 'REVIEW_REQUIRED';
  }

  if (hadLocationReject || looksLikeCardLocationRejection(out.main_risk) || !String(out.main_risk || '').trim()) {
    out.main_risk = LOCATION_REVIEW_MSG;
  }

  if (hadLocationReject) {
    const score = Number(out.score);
    const previewScore = Number(previewCtx.PreviewScore);
    const floor = Number.isFinite(previewScore) ? Math.max(previewScore, 7) : 7;
    if (Number.isFinite(score) && score < 7) out.score = Math.max(score, floor);
    if (String(out.recommendation || '').toUpperCase() === 'NO') out.recommendation = 'YES';
  }

  return out;
};

