const assessBulgariaOnlyLocation = (location, workType = '') => {
  const loc = String(location || '').toLowerCase().trim();
  const wt = String(workType || '').toLowerCase().trim();

  if (/relocation|relocate\s*(?:required|to\b)/.test(loc)) {
    return { allowed: false, reason: 'Relocation required.' };
  }

  if (
    /remote europe/.test(loc) ||
    /remote emea/.test(loc) ||
    /emea · remote/.test(loc) ||
    /europe · remote/.test(loc) ||
    /remote worldwide/.test(loc) ||
    /remote global/.test(loc) ||
    /work from anywhere in europe/.test(loc) ||
    /any european countr/.test(loc)
  ) {
    return { allowed: false, reason: 'Remote Europe/EMEA/Worldwide rejected (BG-only workflow).' };
  }

  if (/\bsofia\b/.test(loc) || /remote bulgaria/.test(loc) || /bulgaria · remote/.test(loc)) {
    return { allowed: true, reason: '' };
  }

  if (loc.includes('bulgaria')) {
    return { allowed: true, reason: '' };
  }

  const hasRemote = wt === 'remote' || /\bremote\b/.test(loc);
  const hasHybrid = wt === 'hybrid' || /\bhybrid\b/.test(loc);
  const hasOnsite =
    wt === 'onsite' ||
    wt === 'on-site' ||
    /\bon-?site\b/.test(loc) ||
    /\bonsite\b/.test(loc);

  const foreignCountryPattern =
    /\b(united kingdom|uk|great britain|england|netherlands|spain|france|italy|germany|portugal|switzerland|austria|belgium|ireland|poland|romania|hungary|sweden|norway|denmark|finland|usa|united states|u\.s\.|canada|australia)\b/;

  if (hasRemote && (loc.includes('· remote') || foreignCountryPattern.test(loc))) {
    return { allowed: false, reason: 'Country-specific remote outside Bulgaria rejected.' };
  }

  if (hasHybrid && !loc.includes('bulgaria') && !/\bsofia\b/.test(loc)) {
    return { allowed: false, reason: 'Hybrid outside Bulgaria rejected.' };
  }

  if (hasOnsite && !loc.includes('bulgaria') && !/\bsofia\b/.test(loc)) {
    return { allowed: false, reason: 'On-site outside Bulgaria rejected.' };
  }

  if (hasRemote && !loc.includes('bulgaria') && !/\bsofia\b/.test(loc)) {
    return { allowed: false, reason: 'Ambiguous international remote location rejected (BG-only workflow).' };
  }

  if (!hasRemote && foreignCountryPattern.test(loc)) {
    return { allowed: false, reason: 'Non-Bulgaria location rejected.' };
  }

  if (!loc || loc === 'not specified') {
    return { allowed: false, reason: 'Ambiguous location — BG-only workflow requires Bulgaria, Sofia, or Remote Bulgaria.' };
  }

  return { allowed: false, reason: 'Location not clearly Bulgaria, Sofia, or Remote Bulgaria.' };
};

const applyBulgariaOnlyCardLocationGuard = (ai, location, workType) => {
  const assessment = assessBulgariaOnlyLocation(location, workType);
  if (assessment.allowed) return { ai, guard: { hit: false } };

  const out = { ...ai };
  out.location_fit = 'MISMATCH';
  out.apply = 'NO';
  out.final_decision = 'REJECT';
  out.biggest_risk = `BG-only location guard: ${assessment.reason} Label: "${location}"${workType ? ` (${workType})` : ''}.`;
  return { ai: out, guard: { hit: true, reason: assessment.reason, category: 'BG_ONLY_CARD_LABEL' } };
};

const isBgEligibleCardLocation = (location, workType = '') =>
  assessBulgariaOnlyLocation(location, workType).allowed;

const hasExplicitBgLocationHardReject = (fullJobText) => {
  const text = String(fullJobText || '').toLowerCase();
  return (
    /\bmust\s+be\s+(?:based|located|resident)\s+in\s+(?!bulgaria\b|\bsofia\b)/.test(text) ||
    /\bonly\s+(?:open\s+to\s+)?(?:candidates|applicants|employees)\s+(?:in|from)\s+(?!bulgaria\b|\bsofia\b)/.test(text) ||
    /\bbulgaria\s+(?:is\s+)?not\s+(?:eligible|included|supported|an?\s+option)\b/.test(text) ||
    /\bnot\s+(?:eligible|available|open)\s+(?:in|for)\s+bulgaria\b/.test(text) ||
    /\brelocation\s+(?:to|outside)\s+(?!bulgaria\b|\bsofia\b)/.test(text) ||
    /\b(?:relocation|relocate)\s+required\b/.test(text) ||
    /\bmust\s+relocate\b/.test(text) ||
    /\b(?:hybrid|on-?site|onsite)\s+(?:required|only)\b.{0,40}\b(united kingdom|uk|germany|france|spain|netherlands|italy|portugal|switzerland|romania|poland|usa|united states)\b/.test(text)
  );
};

const detectBgMultiSiteEuropeFlexLanguage = (fullJobText) => {
  const text = String(fullJobText || '').toLowerCase();
  if (hasExplicitBgLocationHardReject(text)) {
    return { flex: false, mentionsBulgariaEligible: false };
  }

  const flexPatterns = [
    /\b(?:may|can|could)\s+be\s+based\b/,
    /\bbased\s+from\s+any\b/,
    /\bfrom\s+any\s+.{0,40}\b(?:site|office|location)s?\b/,
    /\b(?:site|office|offices|location|locations|hub|hubs)\s+(?:across|throughout|within)\s+europe\b/,
    /\bacross\s+europe\b.{0,60}\b(?:site|office|location|hub)s?\b/,
    /\b(?:any|multiple|various)\s+(?:[a-z0-9-]+\s+){0,4}(?:european\s+)?(?:site|office|location)s?\b/,
    /\beuropean\s+(?:site|office|location|hub)s?\b/,
    /\boffices?\s+across\s+europe\b/,
    /\bany\s+european\s+(?:site|office|location)s?\b/,
  ];

  const mentionsBulgariaEligible =
    /\bbulgaria\b/.test(text) ||
    /\bsofia\b/.test(text) ||
    /\bremote\s+bulgaria\b/.test(text);

  const flex = flexPatterns.some((pattern) => pattern.test(text));
  return { flex, mentionsBulgariaEligible };
};

const applyBgMultiSiteEuropeLocationCalibration = (ai, fullJobText, cardLocation, cardWorkType) => {
  if (!isBgEligibleCardLocation(cardLocation, cardWorkType)) {
    return { ai, guard: { hit: false, calibrated: false } };
  }

  const flex = detectBgMultiSiteEuropeFlexLanguage(fullJobText);
  if (!flex.flex) return { ai, guard: { hit: false, calibrated: false } };

  const out = { ...ai };
  out.location_fit = flex.mentionsBulgariaEligible ? 'FULL MATCH' : 'REVIEW_REQUIRED';
  if (String(out.apply || '').toUpperCase() === 'YES') out.apply = 'MONITOR';
  const decision = String(out.final_decision || '').toUpperCase();
  if (decision === 'APPLY NOW' || decision === 'APPLY') out.final_decision = 'MONITOR';

  const note =
    'Posting mentions multiple European sites/offices; confirm Bulgaria remains eligible before applying — not auto-rejected on location.';
  const existingRisk = String(out.biggest_risk || '').trim();
  if (!/multiple european sites|european sites\/offices|bulgaria remains eligible/i.test(existingRisk)) {
    out.biggest_risk = existingRisk ? `${note} ${existingRisk}` : note;
  }

  return {
    ai: out,
    guard: { hit: false, calibrated: true, ...flex },
  };
};

const detectBulgariaOnlyFullJobTextRestriction = (fullJobText, cardLocation, cardWorkType) => {
  const text = String(fullJobText || '').trim();
  if (text.length < 20) return { restricted: false };

  if (isBgEligibleCardLocation(cardLocation, cardWorkType) && detectBgMultiSiteEuropeFlexLanguage(text).flex) {
    return { restricted: false };
  }

  const patterns = [
    { re: /\bremote europe\b/i, reason: 'Remote Europe not eligible (BG-only workflow).' },
    { re: /\bremote emea\b/i, reason: 'Remote EMEA not eligible (BG-only workflow).' },
    { re: /\bremote worldwide\b|\bremote global\b/i, reason: 'Remote Worldwide not eligible (BG-only workflow).' },
    { re: /\bwork from anywhere in europe\b/i, reason: 'Europe-wide remote not eligible (BG-only workflow).' },
    { re: /\bany european countr(?:y|ies)\b/i, reason: 'Europe-wide remote not eligible (BG-only workflow).' },
    { re: /\b(?:relocation|relocate)\s+(?:required|to\b)/i, reason: 'Relocation required.' },
    { re: /\b(?:must|will)\s+relocate\b/i, reason: 'Relocation required.' },
    {
      re: /\bhybrid\b.{0,60}\b(united kingdom|uk|germany|france|spain|netherlands|italy|portugal|switzerland|romania|poland|usa|united states)\b/i,
      reason: 'Hybrid outside Bulgaria rejected.',
    },
    {
      re: /\b(?:on-?site|onsite)\b.{0,60}\b(united kingdom|uk|germany|france|spain|netherlands|italy|portugal|switzerland|romania|poland|usa|united states)\b/i,
      reason: 'On-site outside Bulgaria rejected.',
    },
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern.re);
    if (!match || match.index == null) continue;
    if (isFalsePositiveRestrictionContext(text, match.index)) continue;
    return { restricted: true, evidence: match[0].trim(), reason: pattern.reason };
  }

  return { restricted: false };
};

const applyBulgariaOnlyFullJobTextGuard = (ai, fullJobText, cardLocation, cardWorkType) => {
  const multiSite = applyBgMultiSiteEuropeLocationCalibration(ai, fullJobText, cardLocation, cardWorkType);
  if (multiSite.guard.calibrated) return multiSite;

  const guard = detectBulgariaOnlyFullJobTextRestriction(fullJobText, cardLocation, cardWorkType);
  if (!guard.restricted) return { ai, guard: { hit: false } };

  const out = { ...ai };
  out.location_fit = 'MISMATCH';
  out.apply = 'NO';
  out.final_decision = 'REJECT';
  out.biggest_risk = `BG-only FullJobText location guard: ${guard.reason} Evidence: "${guard.evidence}".`;
  return { ai: out, guard: { hit: true, ...guard } };
};

