// Bulgarian titles — keyword match (avoids regex encoding issues in workflow JSON).
const BG_EXECUTIVE_TITLE_KEYWORDS = [
  'главен изпълнителен директор',
  'изпълнителен директор',
  'президент',
  'генерален мениджър',
  'генерален директор',
  'оперативен директор',
  'търговски директор',
  'директор',
