  'ръководител',
  'ръководител отдел',
  'оперативен мениджър',
  'търговски мениджър',
  'регионален мениджър',
  'мениджър бизнес единица',
  'мениджър направление',
];

const normalizeTitle = (value) =>
  String(value || '')
    .toLowerCase()
    .trim()
    .replace(/[«»"'""]/g, ' ')
    .replace(/\s+/g, ' ');

const isEarlierHardPolicyReject = (item) => {
  if (item.HardReject === true) return true;
  if (item.ExtractionStatus === 'NO_JOB_CARD') return true;
  const stage = String(item.PipelineStage || '').trim().toUpperCase();
  if (stage === 'POLICY_REJECT' || stage === 'NO_JOB_CARD') return true;
  const autoReject = String(item.auto_reject_reason || '').trim();
  if (autoReject) return true;
  return false;
};

const matchesExecutiveTitle = (role) => {
  const title = String(role || '').trim();
  if (!title) return false;
  if (EXCLUDED_TITLE_PATTERNS.some((pattern) => pattern.test(title))) return false;
  if (EXECUTIVE_TITLE_PATTERNS.some((pattern) => pattern.test(title))) return true;
  const normalized = normalizeTitle(title);
  return BG_EXECUTIVE_TITLE_KEYWORDS.some((keyword) => normalized.includes(keyword));
};

const item = $json;
const role = item.Role || '';
const alreadyPasses = item.PreviewPassesThreshold === true;
const hardBlocked = isEarlierHardPolicyReject(item);
const executiveMatch = matchesExecutiveTitle(role);

let previewPassesThreshold = item.PreviewPassesThreshold;
let executiveTitleOverride = false;
let executiveTitleOverrideReason = '';

if (!alreadyPasses && !hardBlocked && executiveMatch) {
  previewPassesThreshold = true;
  executiveTitleOverride = true;
  executiveTitleOverrideReason = `Executive title routing override: "${role}"`;
}

return {
  json: {
    ...item,
    PreviewPassesThreshold: previewPassesThreshold,
    ExecutiveTitleOverride: executiveTitleOverride,
    ExecutiveTitleOverrideReason: executiveTitleOverrideReason,
  },
};
